<?php
namespace Vedairo\Queue;
use Vedairo\Database\DB;
final class Worker { public function __construct(private DB $db){} public function runOnce():bool{$job=$this->db->query("SELECT * FROM jobs WHERE available_at<=NOW() AND reserved_at IS NULL ORDER BY id LIMIT 1")->fetch();if(!$job)return false;$attempts = ((int)$job['attempts']) + 1;$this->db->query('UPDATE jobs SET reserved_at=NOW(),attempts=attempts+1 WHERE id=?',[$job['id']]);try{$payload=json_decode($job['payload'],true)??[];$class=$payload['class']??null;$args=$payload['args']??[];if(!$class||!class_exists($class))throw new \RuntimeException('Invalid job');$obj=new $class(...$args);$obj->handle();$this->db->query('DELETE FROM jobs WHERE id=?',[$job['id']]);}catch(\Throwable $e){$this->db->query('UPDATE jobs SET reserved_at=NULL,last_error=?,available_at=DATE_ADD(NOW(),INTERVAL LEAST(attempts*10,300) SECOND) WHERE id=?',[$e->getMessage(),$job['id']]);if($attempts>=5){$this->db->query('INSERT INTO failed_jobs(uuid,payload,exception,failed_at) VALUES(?,?,?,NOW())',[bin2hex(random_bytes(16)),$job['payload'],$e->getMessage()]);$this->db->query('DELETE FROM jobs WHERE id=?',[$job['id']]);}}return true;}}
